#!/usr/bin/env bash
# Generated by dev-core worktreeScaffold — concerns: env-files, bun-install-warmup, lefthook-hookspath-fix
# Plus Chemin A extras: apps/*/.dev.vars.example
# Re-generate base with worktreeScaffold; keep CF block when re-composing.
set -euo pipefail

# ─── env-files ──────────────────────────────────────────
if [ -f .env.example ] && [ ! -f .env ]; then
  cp .env.example .env
  echo "worktree-setup: created .env from .env.example"
fi

# Cloudflare Worker local secrets (gitignored)
shopt -s nullglob
for example in apps/*/.dev.vars.example; do
  destination="${example%.example}"
  if [ -e "$destination" ] || [ -L "$destination" ]; then
    continue
  fi

  cp "$example" "$destination"
  echo "worktree-setup: created ${destination} from .dev.vars.example"
done
shopt -u nullglob

# ─── bun-install-warmup ──────────────────────────────────────────
# --minimum-release-age 0: install the lock as reviewed. bunfig.toml's gate is meant for new resolutions,
# but Bun 1.4.0 also rejects a lock entry younger than the gate (docs/kit/security-dependabot.md).
lock_snapshot=$(mktemp)
trap 'rm -f "$lock_snapshot"' EXIT
cp bun.lock "$lock_snapshot"
bun install --minimum-release-age 0
if ! cmp -s bun.lock "$lock_snapshot"; then
  echo "worktree-setup: bun install changed bun.lock; review and commit the lockfile normalization" >&2
  exit 1
fi
rm -f "$lock_snapshot"
trap - EXIT

# ─── lefthook-hookspath-fix ──────────────────────────────────────────
# in worktrees, lefthook installs core.hooksPath relative to the worktree git dir (wrong —
# git uses the common dir for hooks). unset so git falls back to the default hooks path.
GIT_DIR=$(git rev-parse --git-dir 2>/dev/null)
GIT_COMMON_DIR=$(git rev-parse --git-common-dir 2>/dev/null)
if [ "${GIT_DIR}" != "${GIT_COMMON_DIR}" ]; then
  git config --unset-all core.hooksPath 2>/dev/null || true
fi
